module.exports = {
    onConnect: function(transport, config) {
        engine.setStatus("connecting", "Connecting to X32/M32 OSC...");
    },
    onTransportReady: function(transport, config) {
        engine.setStatus("connected", "X32 / M32 Ready");
        var xremote = engine.osc.encode("/xremote", []);
        transport.sendBytes(xremote);
    },
    onHeartbeat: function(transport) {
        var xremote = engine.osc.encode("/xremote", []);
        transport.sendBytes(xremote);
    },
    onAction: function(transport, actionId, params) {
        if (actionId === "x32_get_channel_mute" || actionId === "get_channel_mute" || actionId === "get_mute") {
            var ch = String(params.channel_id || "01");
            if (ch.length === 1) ch = "0" + ch;
            var isMuted = engine.getVariable("x32_ch_" + ch + "_muted") || "false";
            return "Channel " + ch + " Mute: " + isMuted;
        }
        if (actionId === "x32_get_main_fader" || actionId === "get_main_fader" || actionId === "get_fader") {
            var faderVal = engine.getVariable("x32_main_fader") || "0.75";
            return "Main LR Fader: " + faderVal;
        }
        if (actionId === "x32_mute_ch1" || actionId === "mute_channel") {
            var ch = String(params.channel_id || "01");
            if (ch.length === 1) ch = "0" + ch;
            var bytes = engine.osc.encode("/ch/" + ch + "/mix/on", [0]);
            transport.sendBytes(bytes);
            engine.setVariable("x32_ch_" + ch + "_muted", "true");
            return "Muted Channel " + ch;
        }
        if (actionId === "x32_unmute_ch1" || actionId === "unmute_channel") {
            var ch = String(params.channel_id || "01");
            if (ch.length === 1) ch = "0" + ch;
            var bytes = engine.osc.encode("/ch/" + ch + "/mix/on", [1]);
            transport.sendBytes(bytes);
            engine.setVariable("x32_ch_" + ch + "_muted", "false");
            return "Unmuted Channel " + ch;
        }
        if (actionId === "x32_main_fader" || actionId === "main_fader") {
            var lvl = parseFloat(params.level || "0.75");
            var bytes = engine.osc.encode("/main/st/mix/fader", [lvl]);
            transport.sendBytes(bytes);
            engine.setVariable("x32_main_fader", String(lvl));
            return "Set Main LR Fader to " + lvl;
        }
        return "X32 Action Executed";
    },
    onMessage: function(transport, text, bytes) {
        var msg = engine.osc.decode(bytes);
        if (!msg || !msg.address) return;
        var addr = msg.address;
        var args = msg.args || [];

        var chMute = addr.match(/\/ch\/(\d{2})\/mix\/on$/);
        if (chMute && args.length > 0) {
            var ch = chMute[1];
            var isOn = (args[0] === 1 || args[0] === true || args[0] === "1");
            engine.setVariable("x32_ch_" + ch + "_muted", isOn ? "false" : "true");
        }

        var fader = addr.match(/\/ch\/(\d{2})\/mix\/fader$/);
        if (fader && args.length > 0) {
            var ch = fader[1];
            var val = typeof args[0] === "number" ? args[0].toFixed(2) : String(args[0]);
            engine.setVariable("x32_ch_" + ch + "_fader", val);
        }

        if (addr === "/main/st/mix/fader" && args.length > 0) {
            var val = typeof args[0] === "number" ? args[0].toFixed(2) : String(args[0]);
            engine.setVariable("x32_main_fader", val);
        }
    }
};
